# Load all experiments
dfs = {}
for i in range(1, 6):
    dfs[i] = pd.read_csv(f"experiment_{i}_csv")
    print(f"\n=== Experiment {i} ===")
    print(f"Shape: {dfs[i].shape}")
    print(dfs[i].columns.tolist())
    for col in dfs[i].columns:
        if dfs[i][col].dtype in ['float64', 'int64']:
            print(f"  {col}: mean={dfs[i][col].mean():.3f}, std={dfs[i][col].std():.3f}")

# Extract CR and DRC from column names or data
print("\n\n=== COMPARISON OF RETENTION BY CONDITION ===")
for i, df in dfs.items():
    cr = None
    drc = None
    ret = df['CapacityRetention'].mean() if 'CapacityRetention' in df.columns else None
    # Check for ChargeRate column
    for col in df.columns:
        if 'charge' in col.lower():
            cr = df[col].mean()
        if 'dry' in col.lower() or 'drc' in col.lower():
            drc = df[col].mean()
    print(f"Exp{i}: CR={cr}, DRC={drc}, Retention={ret:.3f}")
